\mathrm{df\text{-}recursive\text{-}function\text{-}class}\ \vdash\
\left\{
\begin{aligned}
\mathrm{PartRec}_k
&\coloneqq\{f:\mathbb N^k\rightharpoonup\mathbb N:\mathrm{PartRec}(f)\},\\
\mathrm{Rec}_k
&\coloneqq\{f:\mathbb N^k\to\mathbb N:\mathrm{Rec}(f)\},\\
\mathrm{RecPred}_k
&\coloneqq\{P\subseteq\mathbb N^k:\chi_P\in\mathrm{Rec}_k\},\\
\chi_P(\vec n)
&\coloneqq\begin{cases}1,&\vec n\in P,\\0,&\vec n\notin P.\end{cases}
\end{aligned}
\right.
